                />
              </ComposedChart>
            </ResponsiveContainer>
          </div>
        </ChartCard>
      ) : null}

      {panel === "failure" ? (
        <div className="grid gap-6 lg:grid-cols-2">
          <ChartCard
            title="Why corridor miles fail the pair test"
            subtitle="Desk attribution of unqualified segment-miles"
          >
            <div className="h-80">
              <ResponsiveContainer width="100%" height="100%">
                <BarChart
                  data={[...FAILURE_MODES]}
