  nationalGapSharePct: HEADLINE.unqualifiedSharePct,
  top5GapMiles: topGapStates(5).reduce((a, r) => a + r.gapMiles, 0),
  westGapSharePct: REGION_ROLLUP.find((r) => r.region === "West")?.gapSharePct ?? 0,
