  fboCertified: STATE_GAPS.filter((s) => s.fboStatus === "certified").length,
  meanGapSharePct:
    Math.round(
      (STATE_GAPS.reduce((a, r) => a + r.gapSharePct, 0) / STATE_GAPS.length) * 10,
    ) / 10,
} as const;

