  { bucket: "60%+ gap", minPct: 60, maxPct: 100, states: 0, gapMiles: 0, afcMiles: 0 },
].map((b) => {
  const rows = STATE_GAPS.filter((s) => s.gapSharePct >= b.minPct && s.gapSharePct < (b.maxPct === 100 ? 101 : b.maxPct));
  return {
    ...b,
